var a=`1045-rawon`;var n=`world-1045`;var t=`ID`;var s=`southeast-asia`;var r=4;var o=130;var l={en:`Rawon`,ua:`Равон`};var d={en:`Rawon is a dish from Indonesia prepared with beef shank, shallot, garlic, lemongrass. This is a home-scale version with measured ingredients in the individual steps where they are used. Rawon-inspired beef soup: keluwak nuts, essential for the black color and characteristic taste, are absent; black lime is NOT equivalent.`,ua:`Равон, страва кухні країни Індонезія, яку готують із таких продуктів: яловича гомілка, цибуля шалот, часник, лемонграс. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Лише суп за мотивами равону: горіхів келувак, визначальних для чорного кольору та смаку, немає; чорний лайм НЕ є рівноцінною заміною.`};var h=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`beef-shank`,780,`g`],[`canola-oil`,30,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`shallot`,130,`g`],[`garlic`,5,`clove`],[`ground-coriander`,7,`g`],[`ground-turmeric`,4,`g`]]},{en:`Braise the beef until tender in seasoned broth. Without keluwak, this is only a rawon-inspired soup and will not have traditional dark color or flavor.`,ua:`Тушкуйте яловичину у пряному бульйоні до м’якості. Без келуваку це лише суп за мотивами равону без традиційного темного кольору й смаку.`,t:[`braising`],m:105,i:[[`water`,1100,`ml`],[`lemongrass`,2,`pcs`],[`black-lime`,2,`pcs`],[`tamarind-concentrate`,28,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`bean-sprouts`,190,`g`],[`green-onion`,30,`g`]]}];var u={slug:a,id:n,country:`ID`,region:s,servings:4,minutes:130,title:l,text:d,steps:h};export{t as country,u as default,n as id,o as minutes,s as region,r as servings,a as slug,h as steps,d as text,l as title};